    strict_runtime_proof_id: strictRuntimeProofId ?? null,
    proofLedgerId: proofLedgerId ?? null,
    proof_ledger_id: proofLedgerId ?? null,
    adapterResultHash: adapterResultHash ?? null,
    adapter_result_hash: adapterResultHash ?? null,
