function failedGateObjects(codes) {
  return compactStringList(codes).map((code) => ({ code }));
}

function ledgerVisualOracleArtifactBindingEvidence(proofLedger, visual = {}) {
  const visualRecords = ledgerRecordsFromValue(proofLedger).filter(ledgerRecordHasVisualOutput);
  const actualHashesByRole = visualImageHashesByRole(visual);
  const requiredRoles = ['before', 'after', 'diff'];
  const records = visualRecords.map((record, index) => {
    const artifacts = ledgerRecordVisualOracleArtifacts(record);
    const expectedHashesByRole = declaredVisualArtifactHashesByRole(artifacts);
    const missingDeclaredRoles = requiredRoles.filter((role) => !expectedHashesByRole.get(role));
    const missingActualRoles = requiredRoles.filter((role) =>
      expectedHashesByRole.get(role) && !actualHashesByRole.get(role)
    );
    const mismatchedRoles = requiredRoles.filter((role) => {
      const expected = expectedHashesByRole.get(role);
      const actual = actualHashesByRole.get(role);
      return Boolean(expected) && Boolean(actual) && expected !== actual;
    });
    const accepted =
      missingDeclaredRoles.length === 0
      && missingActualRoles.length === 0
      && mismatchedRoles.length === 0;
    return {
      index,
      accepted,
      expectedHashesByRole: Object.fromEntries(expectedHashesByRole),
      expected_hashes_by_role: Object.fromEntries(expectedHashesByRole),
      actualHashesByRole: Object.fromEntries(actualHashesByRole),
      actual_hashes_by_role: Object.fromEntries(actualHashesByRole),
      missingDeclaredRoles,
      missing_declared_roles: missingDeclaredRoles,
      missingActualRoles,
      missing_actual_roles: missingActualRoles,
      mismatchedRoles,
      mismatched_roles: mismatchedRoles,
    };
  });
  const failedGates = compactStringList([
    visualRecords.length > 0 ? null : 'ledger_visual_oracle_record_missing',
    records.length === visualRecords.length && records.length > 0
      ? null
      : 'ledger_visual_oracle_artifacts_missing',
    records.every((record) => record.missingDeclaredRoles.length === 0)
      ? null
      : 'ledger_visual_oracle_artifact_hash_missing',
    records.every((record) => record.missingActualRoles.length === 0)
      ? null
      : 'accepted_visual_artifact_hash_missing',
    records.every((record) => record.mismatchedRoles.length === 0)
      ? null
      : 'ledger_visual_oracle_artifact_hash_mismatch',
  ]);
  return {
    schemaVersion: 'synthi.gpu_hmr.ledger_visual_oracle_artifact_binding.v1',
    schema_version: 'synthi.gpu_hmr.ledger_visual_oracle_artifact_binding.v1',
    accepted: failedGates.length === 0,
    recordCount: visualRecords.length,
    record_count: visualRecords.length,
    requiredRoles,
    required_roles: requiredRoles,
    actualHashesByRole: Object.fromEntries(actualHashesByRole),
    actual_hashes_by_role: Object.fromEntries(actualHashesByRole),
    records,
    failedGates: failedGateObjects(failedGates),
    failed_gates: failedGateObjects(failedGates),
  };
}

async function resolveComputeOracleArtifactPaths(artifacts, repoRoot, baseDir) {
  const out = { ...artifacts };
  const locators = computeArtifactCasLocators(artifacts);
  const casEntries = [];
  for (const [snakeName, camelName, role] of [
    ['raw_readback_bin', 'rawReadbackBin', 'raw_readback'],
    ['readback_schema_json', 'readbackSchemaJson', 'readback_schema'],
    ['rendered_card_png', 'renderedCardPng', 'rendered_card'],
  ]) {
    const value = firstText(out[snakeName], out[camelName]);
    const expectedHash = computeArtifactCasExpectedHash(artifacts, role);
    const locator = computeArtifactCasLocatorForRole(locators, role, expectedHash);
    if (locator) {
      const validation = await validateComputeArtifactCasLocator(locator, repoRoot, baseDir, artifacts);
      const accepted = validation?.accepted === true && firstText(validation.localPath, validation.local_path);
      const entry = {
        role,
        accepted: Boolean(accepted),
        path: accepted ? firstText(validation.localPath, validation.local_path) : null,
        contentHash: validation?.contentHash ?? null,
        content_hash: validation?.contentHash ?? null,
        manifestHash: validation?.manifestHash ?? null,
        manifest_hash: validation?.manifestHash ?? null,
        reasons: validation?.reasons ?? [],
        gaps: validation?.gaps ?? [],
      };
      casEntries.push(entry);
      if (accepted) {
        out[snakeName] = entry.path;
        out[camelName] = entry.path;
      } else {
        delete out[snakeName];
        delete out[camelName];
      }
      continue;
    }
    if (value) {
      const resolved = resolveEvidencePath(value, repoRoot, baseDir);
      if (!resolved) continue;
      out[snakeName] = resolved;
      out[camelName] = resolved;
    }
  }
  const locatorCount = locators.length;
  const acceptedCount = casEntries.filter((entry) => entry.accepted === true).length;
  if (locatorCount > 0 || casEntries.length > 0) {
    out.compute_artifact_cas_resolution = {
      schemaVersion: 'synthi.gpu_hmr.compute_artifact_cas_resolution.v1',
      schema_version: 'synthi.gpu_hmr.compute_artifact_cas_resolution.v1',
      proofAuthority: 'compute_artifact_transport_integrity_only',
      proof_authority: 'compute_artifact_transport_integrity_only',
      acceptedForGpuHmr: false,
      accepted_for_gpu_hmr: false,
      gpuHmrSuccess: false,
      gpu_hmr_success: false,
      locatorCount,
      locator_count: locatorCount,
      acceptedCount,
      accepted_count: acceptedCount,
      accepted: locatorCount > 0 && acceptedCount === locatorCount,
      entries: casEntries,
      failedGates: compactStringList([
        locatorCount > 0 && acceptedCount !== locatorCount
          ? 'compute_oracle_artifact_cas_locator_validation_failed'
          : null,
      ]),
      failed_gates: compactStringList([
        locatorCount > 0 && acceptedCount !== locatorCount
          ? 'compute_oracle_artifact_cas_locator_validation_failed'
          : null,
      ]),
    };
    out.computeArtifactCasResolution = out.compute_artifact_cas_resolution;
  }
  return out;
}

async function realRocmComputeOracleFileIntegrityFacet(proofLedger, repoRoot, baseDir) {
  const computeRecord = ledgerRecordsFromValue(proofLedger)
    .find((record) => Object.keys(ledgerRecordComputeOracleArtifacts(record)).length > 0);
  const computeArtifacts = computeRecord ? ledgerRecordComputeOracleArtifacts(computeRecord) : {};
  if (Object.keys(computeArtifacts).length === 0) {
    return {
      present: false,
      accepted: false,
      source: 'missing',
      failedGates: [{ code: 'compute_oracle_artifacts_missing' }],
    };
  }
  const resolvedArtifacts = await resolveComputeOracleArtifactPaths(computeArtifacts, repoRoot, baseDir);
  const enriched = await computeOracleArtifactsFromFiles(resolvedArtifacts, {
    allowedRoots: computeArtifactCasAllowedRoots(repoRoot, baseDir, resolvedArtifacts),
    artifactRoot: trustedComputeArtifactCasRoot(repoRoot, baseDir),
  });
  const verification = compactObject(
    enriched?.raw_readback_verification
    ?? enriched?.rawReadbackVerification,
  );
  const rawReadbackPath = firstText(resolvedArtifacts.raw_readback_bin, resolvedArtifacts.rawReadbackBin);
  const schemaPath = firstText(resolvedArtifacts.readback_schema_json, resolvedArtifacts.readbackSchemaJson);
  const renderedCardPath = firstText(resolvedArtifacts.rendered_card_png, resolvedArtifacts.renderedCardPng);
  let renderedCard = {
    present: Boolean(renderedCardPath),
    decoded: false,
    decodeError: null,
    format: null,
    width: null,
    height: null,
  };
  if (renderedCardPath) {
    try {
      const metadata = await sharp(renderedCardPath).metadata();
      renderedCard = {
        present: true,
        decoded: true,
        decodeError: null,
        format: metadata.format ?? null,
        width: metadata.width ?? null,
        height: metadata.height ?? null,
      };
    } catch (error) {
      renderedCard = {
        present: true,
        decoded: false,
        decodeError: error?.message ? String(error.message) : String(error),
        format: null,
        width: null,
        height: null,
      };
    }
  }
  const rawReadbackByteLength = finiteNumber(
    verification.byte_length
    ?? verification.byteLength,
  );
  const schemaByteLength = finiteNumber(
    verification.readback_schema_byte_length
    ?? verification.readbackSchemaByteLength,
  );
  const hashVerified =
    verification.hash_verified === true
    || verification.hashVerified === true;
  const deterministicSliceHashVerified =
    verification.deterministic_slice_hash_verified === true
    || verification.deterministicSliceHashVerified === true;
  const outputEvent = compactObject(computeRecord?.output_event ?? computeRecord?.outputEvent);
  const outputOracle = compactObject(outputEvent.output_oracle ?? outputEvent.outputOracle);
  const declaredRawReadbackHash = firstText(
    resolvedArtifacts.raw_readback_hash,
    resolvedArtifacts.rawReadbackHash,
  );
  const schemaHash = firstText(
    enriched?.readback_schema_hash,
    enriched?.readbackSchemaHash,
    verification.readback_schema_hash,
    verification.readbackSchemaHash,
  );
  const deterministicSliceHash = firstText(
    enriched?.deterministic_slice_hash,
    enriched?.deterministicSliceHash,
    enriched?.deterministic_slice?.hash,
    enriched?.deterministicSlice?.hash,
    verification.deterministic_slice_hash,
    verification.deterministicSliceHash,
  );
  const checksumBefore = firstText(enriched?.checksum_before, enriched?.checksumBefore);
  const checksumAfter = firstText(enriched?.checksum_after, enriched?.checksumAfter);
  const outputChangeExpected =
    firstBool(enriched?.output_change_expected, enriched?.outputChangeExpected) !== false;
  const computeArtifactCasResolution = compactObject(
    resolvedArtifacts.compute_artifact_cas_resolution
    ?? resolvedArtifacts.computeArtifactCasResolution,
  );
  const casFailedGates = compactStringList(
    computeArtifactCasResolution.failedGates
    ?? computeArtifactCasResolution.failed_gates,
  ).map((code) => ({ code }));
  const expectedOutputVerified = firstBool(
    enriched?.expected_output_verified,
    enriched?.expectedOutputVerified,
    verification.expected_output_verified,
    verification.expectedOutputVerified,
    outputEvent.expected_output_verified,
    outputEvent.expectedOutputVerified,
    outputOracle.expected_output_verified,
    outputOracle.expectedOutputVerified,
  ) === true;
  const timestampAfterDispatch = finiteNumber(
    enriched?.timestamp_after_dispatch
    ?? enriched?.timestampAfterDispatch,
  );
  const artifactEpoch = firstEpochText(enriched?.epoch, enriched?.epoch_id, enriched?.epochId);
  const outputEpoch = firstEpochText(outputEvent.epoch, outputEvent.epoch_id, outputEvent.epochId);
  const epochMatches = artifactEpoch && outputEpoch ? artifactEpoch === outputEpoch : Boolean(artifactEpoch);
  const semanticFailedGates = compactStringList([
    declaredRawReadbackHash ? null : 'compute_oracle_raw_readback_hash_declared_missing',
    schemaHash ? null : 'compute_oracle_readback_schema_hash_missing',
    deterministicSliceHash ? null : 'compute_oracle_deterministic_slice_hash_missing',
    checksumBefore ? null : 'compute_oracle_checksum_before_missing',
    checksumAfter ? null : 'compute_oracle_checksum_after_missing',
    outputChangeExpected && checksumBefore && checksumAfter && checksumBefore === checksumAfter
      ? 'compute_oracle_checksum_unchanged'
      : null,
    expectedOutputVerified ? null : 'compute_oracle_expected_output_not_verified',
    timestampAfterDispatch !== null ? null : 'compute_oracle_timestamp_after_dispatch_missing',
    artifactEpoch ? null : 'compute_oracle_epoch_missing',
    epochMatches ? null : 'compute_oracle_epoch_mismatch',
  ]).map((code) => ({ code }));
  const fileFailedGates = [
    ...casFailedGates,
    ...compactStringList([
    rawReadbackPath ? null : 'compute_oracle_raw_readback_path_missing',
    hashVerified ? null : 'compute_oracle_raw_readback_hash_unverified',
    rawReadbackByteLength && rawReadbackByteLength > 0 ? null : 'compute_oracle_raw_readback_bytes_missing',
    deterministicSliceHashVerified ? null : 'compute_oracle_deterministic_slice_hash_unverified',
    verification.raw_readback_read_error ? 'compute_oracle_raw_readback_unreadable' : null,
    schemaPath ? null : 'compute_oracle_readback_schema_path_missing',
    schemaByteLength && schemaByteLength > 0 ? null : 'compute_oracle_readback_schema_bytes_missing',
    verification.readback_schema_read_error ? 'compute_oracle_readback_schema_unreadable' : null,
    renderedCard.present ? null : 'compute_oracle_rendered_card_path_missing',
    renderedCard.decoded ? null : 'compute_oracle_rendered_card_decode_failed',
    renderedCard.decoded && renderedCard.format === 'png' ? null : 'compute_oracle_rendered_card_not_png',
  ]).map((code) => ({ code }))];
  const failedGates = [...fileFailedGates, ...semanticFailedGates];
  return {
    present: true,
    accepted: failedGates.length === 0,
    source: 'matrix_verified_compute_oracle_files',
    failedGates,
    fileIntegrityAccepted: fileFailedGates.length === 0,
    file_integrity_accepted: fileFailedGates.length === 0,
    semanticAccepted: semanticFailedGates.length === 0,
    semantic_accepted: semanticFailedGates.length === 0,
    rawReadbackHash: firstText(enriched?.raw_readback_hash, enriched?.rawReadbackHash),
    rawReadbackByteLength,
    rawReadbackHashVerified: hashVerified,
    rawReadbackHashDeclared: Boolean(declaredRawReadbackHash),
    raw_readback_hash_declared: Boolean(declaredRawReadbackHash),
    readbackSchemaHash: schemaHash,
    readback_schema_hash: schemaHash,
    deterministicSliceHashVerified,
    deterministicSliceHash,
    deterministic_slice_hash: deterministicSliceHash,
    checksumBefore,
    checksum_before: checksumBefore,
    checksumAfter,
    checksum_after: checksumAfter,
    expectedOutputVerified,
    expected_output_verified: expectedOutputVerified,
    timestampAfterDispatch,
    timestamp_after_dispatch: timestampAfterDispatch,
    epoch: artifactEpoch ?? null,
    readbackSchemaByteLength: schemaByteLength,
    readbackSchemaReadError: firstText(verification.readback_schema_read_error, verification.readbackSchemaReadError),
    renderedCard,
    rawReadbackReadError: firstText(verification.raw_readback_read_error, verification.rawReadbackReadError),
    computeArtifactCasResolution: Object.keys(computeArtifactCasResolution).length > 0
      ? computeArtifactCasResolution
      : null,
    compute_artifact_cas_resolution: Object.keys(computeArtifactCasResolution).length > 0
      ? computeArtifactCasResolution
      : null,
  };
}

function runtimeChainOutputOracleBindingOverlay(runtimeChain) {
  const chain = compactObject(runtimeChain);
  if (chain.accepted !== true) return null;
  const outputTargetId = firstText(chain.outputTargetId, chain.output_target_id);
  if (!outputTargetId) return null;
  const dispatchId = firstText(chain.dispatchId, chain.dispatch_id);
  const afterDispatchId = firstText(
    chain.afterDispatchId,
    chain.after_dispatch_id,
    chain.outputAfterDispatchId,
    chain.output_after_dispatch_id,
  );
  return {
    source: 'accepted_runtime_chain_overlay',
    outputTargetId,
    dispatchTargetId: outputTargetId,
    oracleTargetId: outputTargetId,
    dispatchId,
    afterDispatchId,
    evidenceRef: firstText(chain.proofId, chain.proof_id, chain.runtimeChainId, chain.runtime_chain_id),
  };
}

function firstOutputOracleTargetValue(...values) {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
    const objectValue = compactObject(value);
    if (Object.keys(objectValue).length > 0) return objectValue;
  }
  return null;
}

function ledgerRecordMissingOutputTargetBinding(ledgerRecord = {}) {
  const record = compactObject(ledgerRecord);
  const dispatchEvent = compactObject(record.dispatchEvent ?? record.dispatch_event);
  const outputEvent = compactObject(record.outputEvent ?? record.output_event);
  return !eventOutputTargetId(dispatchEvent) || !eventOutputTargetId(outputEvent);
}

function outputOracleTargetSupplementalBinding(targetValue = {}, ledgerRecord = {}) {
  const explicitTarget = typeof targetValue === 'string'
    ? { target: targetValue }
    : compactObject(targetValue);
  const recordTargetValue = ledgerRecord.outputOracleTarget ?? ledgerRecord.output_oracle_target;
  const recordTarget = typeof recordTargetValue === 'string'
    ? { target: recordTargetValue }
    : compactObject(recordTargetValue);
  const target = { ...recordTarget, ...explicitTarget };
  if (Object.keys(target).length === 0) return null;
  const outputTargetId = firstText(
    target.outputTargetId,
    target.output_target_id,
    target.oracleTargetId,
    target.oracle_target_id,
    target.targetId,
    target.target_id,
    target.target,
    target.id,
    target.name,
  );
  if (!outputTargetId) return null;
  const dispatchEvent = compactObject(ledgerRecord.dispatchEvent ?? ledgerRecord.dispatch_event);
  const outputEvent = compactObject(ledgerRecord.outputEvent ?? ledgerRecord.output_event);
  const dispatchId = firstText(dispatchEvent.id, dispatchEvent.dispatch_id, dispatchEvent.dispatchId);
  const afterDispatchId = firstText(
    outputEvent.after_dispatch_id,
    outputEvent.afterDispatchId,
    outputEvent.dispatch_id,
    outputEvent.dispatchId,
  );
  return {
    source: 'proof_artifact_output_oracle_target_binding',
    outputTargetId,
    output_target_id: outputTargetId,
    dispatchTargetId: outputTargetId,
    dispatch_target_id: outputTargetId,
    oracleTargetId: outputTargetId,
    oracle_target_id: outputTargetId,
    dispatchId,
    dispatch_id: dispatchId,
    afterDispatchId,
    after_dispatch_id: afterDispatchId,
    evidenceRef: `output-oracle-target:${stableJsonHash({
      outputTargetId,
      dispatchId,
      afterDispatchId,
      target,
    })}`,
    evidence_ref: `output-oracle-target:${stableJsonHash({
      outputTargetId,
      dispatchId,
      afterDispatchId,
      target,
    })}`,
  };
}

function ledgerOutputOracleBindingEvidence(proofLedger, options = {}) {
  const records = ledgerRecordsFromValue(proofLedger);
  const recordTargetBindings = records.map((record) =>
    outputOracleTargetSupplementalBinding(undefined, record)
  );
  const supplementalBindings = compactObjectList([
    ...recordTargetBindings,
    runtimeChainOutputOracleBindingOverlay(options.runtimeChain ?? options.runtime_chain),
    ...(Array.isArray(options.supplementalBindings) ? options.supplementalBindings : []),
    ...(Array.isArray(options.supplemental_bindings) ? options.supplemental_bindings : []),
  ]);
  const dispatchTargetEvidence = [];
  const oracleTargetEvidence = [];
  const dispatchIdEvidence = [];
  const afterDispatchEvidence = [];
  const evidenceRefs = [];
  for (const record of records) {
    const dispatchEvent = compactObject(record.dispatchEvent ?? record.dispatch_event);
    const outputEvent = compactObject(record.outputEvent ?? record.output_event);
    const dispatchId = firstText(dispatchEvent.id, dispatchEvent.dispatch_id, dispatchEvent.dispatchId);
    const afterDispatchId = firstText(
      outputEvent.after_dispatch_id,
      outputEvent.afterDispatchId,
      outputEvent.dispatch_id,
      outputEvent.dispatchId,
    );
    const dispatchTarget = eventOutputTargetId(dispatchEvent);
    const oracleTarget = eventOutputTargetId(outputEvent);
    dispatchIdEvidence.push(dispatchId);
    afterDispatchEvidence.push(afterDispatchId);
    dispatchTargetEvidence.push(dispatchTarget);
    oracleTargetEvidence.push(oracleTarget);
    evidenceRefs.push(dispatchId, afterDispatchId, dispatchTarget, oracleTarget);
  }
  for (const binding of supplementalBindings) {
    const dispatchTarget = firstText(
      binding.dispatchTargetId,
      binding.dispatch_target_id,
      binding.outputTargetId,
      binding.output_target_id,
    );
    const oracleTarget = firstText(
      binding.oracleTargetId,
      binding.oracle_target_id,
      binding.outputTargetId,
      binding.output_target_id,
    );
    const dispatchId = firstText(binding.dispatchId, binding.dispatch_id);
    const afterDispatchId = firstText(binding.afterDispatchId, binding.after_dispatch_id);
    dispatchTargetEvidence.push(dispatchTarget);
    oracleTargetEvidence.push(oracleTarget);
    if (dispatchId && afterDispatchId) {
      dispatchIdEvidence.push(dispatchId);
      afterDispatchEvidence.push(afterDispatchId);
    }
    evidenceRefs.push(
      binding.source,
      binding.evidenceRef,
      binding.evidence_ref,
      dispatchTarget,
      oracleTarget,
      dispatchId,
      afterDispatchId,
    );
  }
  const dispatchIds = compactStringList(dispatchIdEvidence);
  const afterDispatchIds = compactStringList(afterDispatchEvidence);
  const dispatchOutputTargets = compactStringList(dispatchTargetEvidence);
  const oracleOutputTargets = compactStringList(oracleTargetEvidence);
  const outputTargetIds = compactStringList([
    ...dispatchOutputTargets,
    ...oracleOutputTargets,
  ]);
  const dispatchAfterBindingValues = compactStringList([
    ...dispatchIds,
    ...afterDispatchIds,
  ]);
  const outputTargetMatched =
    dispatchOutputTargets.length > 0
    && oracleOutputTargets.length > 0
    && outputTargetIds.length === 1;
  const outputAfterDispatchMatched =
    dispatchIds.length > 0
    && afterDispatchIds.length > 0
    && dispatchAfterBindingValues.length === 1;
  const failedGates = compactStringList([
    records.length > 0 ? null : 'output_oracle_binding_record_missing',
    dispatchIds.length > 0 ? null : 'output_oracle_binding_dispatch_id_missing',
    afterDispatchIds.length > 0 ? null : 'output_oracle_binding_after_dispatch_id_missing',
    dispatchOutputTargets.length > 0 ? null : 'output_oracle_binding_dispatch_target_missing',
    oracleOutputTargets.length > 0 ? null : 'output_oracle_binding_oracle_target_missing',
    outputTargetMatched ? null : 'output_oracle_binding_target_mismatch',
    outputAfterDispatchMatched ? null : 'output_oracle_binding_after_dispatch_mismatch',
  ]);
  return {
    schemaVersion: 'synthi.gpu_hmr.output_oracle_binding.v1',
    schema_version: 'synthi.gpu_hmr.output_oracle_binding.v1',
    present: records.length > 0,
    accepted: failedGates.length === 0,
    outputTargetMatched,
    output_target_matched: outputTargetMatched,
    outputAfterDispatchMatched,
    output_after_dispatch_matched: outputAfterDispatchMatched,
    outputTargetId: outputTargetIds[0] ?? null,
    output_target_id: outputTargetIds[0] ?? null,
    dispatchOutputTargetId: dispatchOutputTargets[0] ?? null,
    dispatch_output_target_id: dispatchOutputTargets[0] ?? null,
    oracleOutputTargetId: oracleOutputTargets[0] ?? null,
    oracle_output_target_id: oracleOutputTargets[0] ?? null,
    dispatchId: dispatchIds[0] ?? null,
    dispatch_id: dispatchIds[0] ?? null,
    afterDispatchId: afterDispatchIds[0] ?? null,
    after_dispatch_id: afterDispatchIds[0] ?? null,
    outputTargetIds,
    output_target_ids: outputTargetIds,
    dispatchIds,
    dispatch_ids: dispatchIds,
    afterDispatchIds,
    after_dispatch_ids: afterDispatchIds,
    supplementalBindingSources: compactStringList(supplementalBindings.map((binding) => binding.source)),
    supplemental_binding_sources: compactStringList(supplementalBindings.map((binding) => binding.source)),
    evidenceRefs: compactStringList(evidenceRefs),
    evidence_refs: compactStringList(evidenceRefs),
    failedGates,
    failed_gates: failedGates,
  };
}

async function ledgerOutputOracleFacet(ledger, proofLedger, visual, repoRoot, baseDir, options = {}) {
  const ledgerAccepted = ledger.present === true
    && ledger.source === 'recomputed_ledger'
    && ledger.gpuHmrSuccess === true
    && ledger.failedInvariants.length === 0;
  const outputBinding = ledgerOutputOracleBindingEvidence(proofLedger, options);
  if (!ledgerAccepted) {
    return {
      accepted: false,
      kind: 'ledger_rejected',
      compute: null,
      outputBinding,
      output_binding: outputBinding,
      failedGates: [{ code: 'proof_ledger_success_required' }],
    };
  }
  const visualLedgerOutput = ledgerRecordsFromValue(proofLedger).some(ledgerRecordHasVisualOutput);
  if (visualLedgerOutput) {
    const visualArtifactBinding = ledgerVisualOracleArtifactBindingEvidence(proofLedger, visual);
    const failedGates = failedGateObjects([
      outputBinding.accepted === true ? null : 'output_oracle_binding_not_accepted',
      visual.present === true && visual.accepted === true ? null : 'visual_oracle_artifacts_not_accepted',
      visualArtifactBinding.accepted === true ? null : 'visual_oracle_artifacts_not_ledger_bound',
      ...compactStringList(outputBinding.failedGates),
      ...compactStringList((visualArtifactBinding.failedGates ?? []).map((failure) => failure.code)),
    ]);
    return {
      accepted: failedGates.length === 0,
      kind: 'visual_oracle',
      compute: null,
      outputBinding,
      output_binding: outputBinding,
      visualArtifactBinding,
      visual_artifact_binding: visualArtifactBinding,
      evidenceRefs: outputBinding.evidenceRefs,
      evidence_refs: outputBinding.evidence_refs,
      failedGates,
      failed_gates: failedGates,
    };
  }
  const compute = await realRocmComputeOracleFileIntegrityFacet(proofLedger, repoRoot, baseDir);
  const failedGates = failedGateObjects([
    outputBinding.accepted === true ? null : 'output_oracle_binding_not_accepted',
    compute.accepted === true ? null : 'compute_oracle_artifacts_not_accepted',
    ...compactStringList(outputBinding.failedGates),
    ...compactStringList((compute.failedGates ?? []).map((failure) => failure.code ?? failure)),
  ]);
  return {
    accepted: failedGates.length === 0,
    kind: 'compute_oracle',
    compute,
    outputBinding,
    output_binding: outputBinding,
    evidenceRefs: outputBinding.evidenceRefs,
    evidence_refs: outputBinding.evidence_refs,
    failedGates,
    failed_gates: failedGates,
  };
}

