    source_first_ingestion: sourceFirstIngestion,
    ledger: {
      present: false,
      proofId: null,
      gpuHmrSuccess: false,
      failedInvariants: [],
    },
    visual: {
      required: false,
      present: false,
      accepted: true,
      imageCount: 0,
      existingImageCount: 0,
      pngImageCount: 0,
      allImagesExist: false,
      allImagesArePng: false,
      images: [],
    },
